export const SPAN_ENHANCE_JS: string = "(function(){\n  var ANSWERS = [\"Yes. Every change Syntra makes is reversible, and the app creates a restore point before optimizing. You can review and undo any tweak at any time.\",\"Syntra fully supports Windows 10 and Windows 11 (64-bit). Older versions are not supported.\",\"If Syntra does not improve your system, contact us within 14 days of purchase for a full refund &mdash; no questions asked.\",\"After booking, a Syntra expert connects to your PC through a secure remote tool. They run the full optimization while you watch, then share a before/after report.\",\"Absolutely. Sessions use encrypted, one-time access that you approve and can end instantly. Access is revoked the moment the session finishes.\",\"No. Syntra only adjusts software settings and clears temporary data &mdash; it never touches your personal files or hardware warranty.\"];\n  var items = Array.prototype.slice.call(document.querySelectorAll('.framer-okz85z-container [tabindex=\"0\"]'));\n  if (!items.length) return;\n  items.forEach(function(item, idx){\n    if (idx >= ANSWERS.length) return;\n    var a = document.createElement('div');\n    a.className = 'syntra-faq-answer';\n    a.textContent = ANSWERS[idx];\n    a.style.cssText = 'display:none;padding:0 2px 24px;font-size:0.9rem;line-height:1.7;color:rgba(255,255,255,0.45);letter-spacing:-0.02em;';\n    item.appendChild(a);\n    item.addEventListener('click', function(){\n      var open = a.style.display === 'block';\n      items.forEach(function(o){\n        var oa = o.querySelector('.syntra-faq-answer');\n        if (oa) oa.style.display = 'none';\n        o.style.backgroundColor = '';\n      });\n      a.style.display = open ? 'none' : 'block';\n      if (!open) item.style.backgroundColor = 'rgba(255,255,255,0.03)';\n    });\n  });\n})();"

